 static string ExactTitle(Record r){var map=new Dictionary<string,string>{{"S2_001","FANTASÍA"},{"S2_002","La Fiesta del Amor"},{"S2_003","RUMORES"},{"S2_004","SOLO UN VESTIDO"},{"S2_005","Tu Atuendo Favorito"},{"S2_006","Vestido de Coraje"},{"S2_008","CLUELESS"},{"S2_009","MINHA MÃE É UMA PEÇA 3"},{"S2_010","WHITE CHICKS"},{"S2_011","AS BRANQUELAS"},{"S2_012","SUITS"},{"S2_013","THE OFFICE"},{"S2_014","CONSULTA AS NOVE"},{"S2_015","O GAMBITO DA VIDA"},{"S2_016","O DISCURSO DE EMILY"},{"S2_017","FOBIAS"},{"S2_018","MARGENS"},{"S2_019","HIV — O terror de José"},{"S2_020","MARTE"},{"S2_021","ENTORPECIDOS"},{"S2_022","CAIU NA REDE, É PEIXE!"},{"S2_024","Oduvaldo e Iracema uma história de amor"},{"S2_025","Love at first sight"},{"S2_026","Forrest Gump"},{"S2_027","GROWN UPS"},{"S2_028","VAI QUE COLA"},{"S2_030","ESCAPISM"},{"S2_031","ESCAPISMO"},{"S2_033","MEAN GIRLS"},{"S2_034","Chaves"}};return map.TryGetValue(r.id,out var s)?s:"";}
