 static void Torus(string name,Vector3 p,float radius,float tube,Quaternion rot,Material mat,Transform parent){var v=new List<Vector3>();var tr=new List<int>();const int u=64,w=10;for(int i=0;i<=u;i++)for(int j=0;j<=w;j++){float a=i*2*Mathf.PI/u,b=j*2*Mathf.PI/w;v.Add(new Vector3((radius+tube*Mathf.Cos(b))*Mathf.Cos(a),tube*Mathf.Sin(b),(radius+tube*Mathf.Cos(b))*Mathf.Sin(a)));}for(int i=0;i<u;i++)for(int j=0;j<w;j++){int a=i*(w+1)+j,b=a+w+1;tr.AddRange(new[]{a,a+1,b,a+1,b+1,b});}var g=MeshObject(name,Store("Torus_"+radius+"_"+tube,new Mesh{vertices=v.ToArray(),triangles=tr.ToArray()}),mat,parent);g.transform.localPosition=p;g.transform.localRotation=rot;}
 static void ImportedVase(Vector3 p,Transform parent){var source=AssetDatabase.LoadAssetAtPath<GameObject>(B+"Models/PolyHaven_CeramicVase/ceramic_vase_03_1k.fbx");if(!source)throw new Exception("Vaso externo não importado");Pedestal(new Vector3(p.x,0,p.z),new Vector3(1,.75f,1),parent);var g=(GameObject)PrefabUtility.InstantiatePrefab(source,scene);g.name="Vaso Poly Haven · James Ray Cock · CC0";g.transform.SetParent(parent,false);var rr=g.GetComponentsInChildren<Renderer>();var b=rr[0].bounds;foreach(var r in rr)b.Encapsulate(r.bounds);g.transform.localScale=Vector3.one*(.85f/b.size.y);b=rr[0].bounds;foreach(var r in rr)b.Encapsulate(r.bounds);g.transform.position+=p-new Vector3(b.center.x,b.min.y,b.center.z);var m=Mat("Ceramica_PolyHaven",Color.white,.26f);m.mainTexture=AssetDatabase.LoadAssetAtPath<Texture2D>(B+"Models/PolyHaven_CeramicVase/ceramic_vase_03_diff_1k.jpg");foreach(var r in rr)r.sharedMaterial=m;}
